INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('50ba4f57-8f56-50e0-a040-423b738da30f', 'd60a22ea-6eb8-5578-a0a7-4d396dc4574b', '16e89615-dbea-5685-aa5f-c415ab5b5ea8', 9, 9, 'እኛ የትናንት ብቻ ነን ምንም አናውቅም፤'),
