  ('59648260-0ffd-5806-a4a4-6d30ac1d5e88', '3fc203e3-d5c5-5905-a789-5c518e60962d', '36ff7134-ed40-5d3c-a2b6-1151d54ea6da', 21, 21, 'በሰው ሁሉ ዘንድ ተረስታለች፥'),
  ('6053a353-c5d4-5604-a376-cd8783fc3d20', '3fc203e3-d5c5-5905-a789-5c518e60962d', '36ff7134-ed40-5d3c-a2b6-1151d54ea6da', 22, 22, 'ሞትና ሲኦል ወሬዋን በጆሮቻችን ሰማን ብለዋል።'),
  ('430b68ce-f608-57fa-a737-60855e2f7d69', '3fc203e3-d5c5-5905-a789-5c518e60962d', '36ff7134-ed40-5d3c-a2b6-1151d54ea6da', 23, 23, '“እግዚአብሔር መንገድዋን አሳመረ፥'),
  ('9bf6f78e-55f8-5865-a98c-c32052d04305', '3fc203e3-d5c5-5905-a789-5c518e60962d', '36ff7134-ed40-5d3c-a2b6-1151d54ea6da', 24, 24, 'እርሱም በሰማይ ያለውን ይመለከታል፥'),
  ('96aa5c66-1363-5c63-a88f-d5f6cac4407e', '3fc203e3-d5c5-5905-a789-5c518e60962d', '36ff7134-ed40-5d3c-a2b6-1151d54ea6da', 25, 25, 'ለነፋስ ሚዛንን'),
  ('3e68ef52-89df-5bc6-abc5-c6b2e0a5dc45', '3fc203e3-d5c5-5905-a789-5c518e60962d', '36ff7134-ed40-5d3c-a2b6-1151d54ea6da', 26, 26, 'እነዚህን በፈጠረ ጊዜ እንዲሁ ዐውቆ ቈጠራቸው።'),
  ('2b6c2ab2-ba3c-5998-aa78-9e97a52ae3b6', '3fc203e3-d5c5-5905-a789-5c518e60962d', '36ff7134-ed40-5d3c-a2b6-1151d54ea6da', 27, 27, 'በዚያን ጊዜ አያት፥ ገለጣትም፤'),
