  ('b31f4fae-ee4a-56f8-aff3-0098e46bb3a1', '37e42584-00f8-589d-ad8e-8af8d9ac9c33', '9c8f7aea-f51b-5170-a46e-4ad51eeb2bde', 1, 1, 'ኢዮብም ምሳሌውን ይመስል ዘንድ ደገመ፥ እንዲህም አለ፦'),
  ('b501caf2-9812-55d0-ad1e-5790e47b988e', '37e42584-00f8-589d-ad8e-8af8d9ac9c33', '9c8f7aea-f51b-5170-a46e-4ad51eeb2bde', 2, 2, '“እግዚአብሔር ይጠብቀኝ እንደ ነበረው ጊዜ፥'),
  ('89a4bfe1-020d-5c31-a4f9-3a6348543309', '37e42584-00f8-589d-ad8e-8af8d9ac9c33', '9c8f7aea-f51b-5170-a46e-4ad51eeb2bde', 3, 3, 'በራስጌዬ ላይ መብራቴ በበራ ጊዜ፥'),
