  ('1ccb9e31-2c93-5595-a5e2-5868c72651cd', '52a4500e-c456-5769-ad43-d41edca636cd', '44907ac7-a087-5643-a906-ecdacee65172', 17, 17, 'የአዜብ ነፋስ በተኮሰ ጊዜ ያንተ ልብስህ የሞቀ ነው።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('c95f7593-5988-53b6-afac-265fbdbad067', '52a4500e-c456-5769-ad43-d41edca636cd', '44907ac7-a087-5643-a906-ecdacee65172', 18, 18, 'እንደ ቀለጠ መስተዋት'),
  ('90325f6f-aee2-5311-ab1c-85bd08b25321', '52a4500e-c456-5769-ad43-d41edca636cd', '44907ac7-a087-5643-a906-ecdacee65172', 19, 19, 'ስለዚህ ንገረኝ! ምን እንለዋለን?'),
