  ('c5ecf273-1ad2-5788-a4bc-0f55ccc246f7', '5a566598-4fa4-5adf-ab5c-21b702270721', '9bc27a2b-0562-58fb-ab3e-b231518976d3', 2, 2, '“ከእኔ ምክርን የሚሸሽግ፥'),
