  ('59dfe91a-6c74-513e-aab5-d919912d99b7', '5a566598-4fa4-5adf-ab5c-21b702270721', '9bc27a2b-0562-58fb-ab3e-b231518976d3', 5, 5, 'ብታውቅ መስፈሪያዋን የወሰነ፥'),
