  ('86f2db89-1cef-54f6-a93a-db3f12fdfbea', '5a566598-4fa4-5adf-ab5c-21b702270721', '9bc27a2b-0562-58fb-ab3e-b231518976d3', 15, 15, 'የኃጥኣንን ብርሃናቸውን ከልክለሃልን?'),
