  ('38c85c13-a9b9-5b69-ab6f-57ef58cea263', '2f79fb9f-b562-5d11-a95f-ec3a16584201', '8d524c66-38f3-5f8c-acfb-c0931bd944c3', 2, 2, 'እርስዋ የምትወልድበትንስ ሙሉ ወራት ትቈጥራለህን?'),
  ('16714943-b344-5024-a1b0-cdf16ccb6755', '2f79fb9f-b562-5d11-a95f-ec3a16584201', '8d524c66-38f3-5f8c-acfb-c0931bd944c3', 3, 3, 'ልጆቻቸውንስ ያለ ፍርሃት አሳድገሃልን?'),
