  ('67033cae-85d7-598a-a396-07d56d56eff5', 'd75ecf61-404d-50d8-aabd-ba8b5ed05140', '07741001-cb1b-5655-a194-c5fcef6908f1', 15, 15, 'ልቡ እንደ ዋሻ ድንጋይ የደነደነ ነው፤'),
  ('e3ddc5c2-2db5-536d-ab25-c36d4ae27964', 'd75ecf61-404d-50d8-aabd-ba8b5ed05140', '07741001-cb1b-5655-a194-c5fcef6908f1', 16, 16, 'በተመለሰም ጊዜ አራዊትና እንስሳ ይፈራሉ፥'),
  ('c7aef97c-ee76-59c9-a827-e430f1bcd287', 'd75ecf61-404d-50d8-aabd-ba8b5ed05140', '07741001-cb1b-5655-a194-c5fcef6908f1', 17, 17, 'ሰይፍና ጦር፥ ፍላጻና መውጊያም ቢያገኙት'),
  ('7d67e097-7ae4-50f5-ade7-7e7bf0cb2c18', 'd75ecf61-404d-50d8-aabd-ba8b5ed05140', '07741001-cb1b-5655-a194-c5fcef6908f1', 18, 18, 'በእርሱ ዘንድ መውጊያና የብረት ልብስ እንደ ገለባ ናቸው።'),
  ('ac381703-3bc5-59f7-ae1e-66dfdd852113', 'd75ecf61-404d-50d8-aabd-ba8b5ed05140', '07741001-cb1b-5655-a194-c5fcef6908f1', 19, 19, 'የናስ ፍላጻ ሊበሳው አይችልም፤'),
  ('6b3592c6-45fb-5880-a523-aeca9469b140', 'd75ecf61-404d-50d8-aabd-ba8b5ed05140', '07741001-cb1b-5655-a194-c5fcef6908f1', 20, 20, 'ድጅኖ ቀሰም ይመስለዋል'),
  ('acdfc6a4-e482-5f7c-a9b6-88c247205cdb', 'd75ecf61-404d-50d8-aabd-ba8b5ed05140', '07741001-cb1b-5655-a194-c5fcef6908f1', 21, 21, 'መኝታው እንደ ስለታም ድንጋይ ነው፤'),
  ('5770efb1-2155-5fa4-a3d7-53d72a317bdd', 'd75ecf61-404d-50d8-aabd-ba8b5ed05140', '07741001-cb1b-5655-a194-c5fcef6908f1', 22, 22, 'ቀላይዋን እንደ ብረት ድስት ያፈላታል፤'),
  ('7af5112c-d586-51f9-a258-b3bc5aac7d69', 'd75ecf61-404d-50d8-aabd-ba8b5ed05140', '07741001-cb1b-5655-a194-c5fcef6908f1', 23, 23, 'የሲኦልም ጥልቀት እንደ ምርኮ ነው።'),
  ('66435c69-bde8-52ef-a72a-e1b40351aff7', 'd75ecf61-404d-50d8-aabd-ba8b5ed05140', '07741001-cb1b-5655-a194-c5fcef6908f1', 24, 24, 'በተፈጠረ ጊዜ መላእክቴ የሣቁበት፥'),
  ('22502c9c-db8d-566b-ac23-8d4c46ccb32f', 'd75ecf61-404d-50d8-aabd-ba8b5ed05140', '07741001-cb1b-5655-a194-c5fcef6908f1', 25, 25, 'ከፍ ያለውን ሁሉ ይመለከታል፤'),
  ('0cbd6906-9a4d-563d-a685-d55f3b2124eb', '84413c86-ae6b-52f8-af26-b0bd09b172cb', '38853764-ee8e-5fef-add9-4eee92cdbcad', 1, 1, 'ኢዮብም መለሰ፥ እግዚአብሔርንም እንዲህ አለው፦'),
  ('4eac8dce-be95-5b5d-ac10-bd5e06fb3b93', '84413c86-ae6b-52f8-af26-b0bd09b172cb', '38853764-ee8e-5fef-add9-4eee92cdbcad', 2, 2, '“ሁሉን ታደርግ ዘንድ ቻይ እንደ ሆንህ፥ የሚሳንህም እንደሌለ ዐወቅሁ።'),
  ('0cc6defa-e8d9-5fb0-ae3d-1a8ac2c38f7f', '84413c86-ae6b-52f8-af26-b0bd09b172cb', '38853764-ee8e-5fef-add9-4eee92cdbcad', 3, 3, 'ምክርን ከአንተ የሚሰውር፥ ቃሉንም ከአንተ የሚሸልግና የሚሸሽግ የሚመስለው ማን ነው? የማላስተውለውንና የማላውቀውንም ታላቅና ድንቅ ነገር የሚነግረኝ ማን ነው?'),
  ('0c40935b-454b-5c53-a10a-8e79ba8f35c8', '84413c86-ae6b-52f8-af26-b0bd09b172cb', '38853764-ee8e-5fef-add9-4eee92cdbcad', 4, 4, '“ጌታ ሆይ፥ እባክህ፥ ስማኝ፥ እኔም ልናገር፤ እጠይቅህማለሁ፥ አንተም አስተምረኝ።'),
  ('b320f582-1170-5fa5-a8cc-38ef3a96cdc6', '84413c86-ae6b-52f8-af26-b0bd09b172cb', '38853764-ee8e-5fef-add9-4eee92cdbcad', 5, 5, 'መስማትንስ ስለ አንተ ቀድሞ በጆሮዬ ሰምቼ ነበር፤ አሁን ግን ዐይኔ አየችህ፤'),
  ('919cbbb6-3836-5e3f-abd9-059f85996b51', '84413c86-ae6b-52f8-af26-b0bd09b172cb', '38853764-ee8e-5fef-add9-4eee92cdbcad', 6, 6, 'ስለዚህ ራሴን እንቃለሁ፤ ሰውነቴም ቀለጠ። እኔ አፈርና አመድ እንደ ሆንሁ አውቃለሁ።”'),
  ('d156c2c7-c351-5b33-aa8e-96807aa32747', '84413c86-ae6b-52f8-af26-b0bd09b172cb', '3a82be6f-599a-572b-a976-d5c582652617', 1, 7, 'እግዚአብሔርም ይህን ቃል ለኢዮብ ከተናገረ በኋላ እግዚአብሔር ቴማናዊውን ኤልፋዝን እንዲህ አለው፥ “እንደ ባሪያዬ እንደ ኢዮብ አንዲት ቅን ነገርን በፊቴ አልተናገራችሁምና አንተና ሁለቱ ባልንጀሮችህ በድላችኋል።'),
  ('d0889437-404d-5e2a-ab2b-719076365816', '84413c86-ae6b-52f8-af26-b0bd09b172cb', '3a82be6f-599a-572b-a976-d5c582652617', 2, 8, 'አሁን እንግዲህ ሰባት ወይፈኖችንና ሰባት አውራ በጎችን ይዛችሁ ወደ ባሪያዬ ወደ ኢዮብ ዘንድ ሂዱ፥ እርሱም የሚቃጠልን መሥዋዕት ስለ ራሳችሁ ያሳርግላችሁ። ባሪያዬም ኢዮብ ስለ እናንተ ይጸልይ፥ እኔም ፊቱን እቀበላለሁ። ስለ እርሱ ባይሆን ባጠፋኋችሁ ነበር። በባሪያዬ በኢዮብ ላይ ቅን ነገርን በፊቴ አልተናገራችሁምና።”'),
  ('559297cd-7ae3-55f0-a74b-e4a90612ae6a', '84413c86-ae6b-52f8-af26-b0bd09b172cb', '3a82be6f-599a-572b-a976-d5c582652617', 3, 9, 'ቴማናዊውም ኤልፋዝ፥ አውኬናዊው በልዳዶስና፥ አሜናዊው ሶፋር ሄደው እግዚአብሔር እንዳዘዛቸው አደረጉ፤ ስለ ኢዮብም ሲል ኀጢአታቸውን ይቅር አላቸው።'),
  ('2428fb22-9166-5d7e-a81f-7f117fe90e2f', '84413c86-ae6b-52f8-af26-b0bd09b172cb', '48f58ee1-b0d3-5be5-af17-c19673b9bedf', 1, 10, 'እግዚአብሔርም ኢዮብን አዳነው። ኢዮብም ስለ ወዳጆቹ ጸለየ፥ እግዚአብሔርም ኀጢአታቸውን ተወላቸው፤ እግዚአብሔርም ቀድሞ በነበረው ገንዘቡ ሁሉ ፋንታ ሁለት እጥፍ ከዚያም በላይ አድርጎ ለኢዮብ ሰጠው።'),
  ('eac9b7ca-60a8-57bf-a515-473a3a969cb7', '84413c86-ae6b-52f8-af26-b0bd09b172cb', '48f58ee1-b0d3-5be5-af17-c19673b9bedf', 2, 11, 'ወንድሞቹና እኅቶቹ ቀድሞም ያውቁት የነበሩት ሁሉ የሆነውን ሁሉ በሰሙ ጊዜ ወደ እርሱ መጡ፥ በቤቱም ከእርሱ ጋር እንጀራ በሉ፥ ጠጡም፤ አጽናኑትም፤ እግዚአብሔርም ባመጣበት ክፉ ነገር ሁሉ አደነቁ፤ እያንዳንዳቸውም ጥማድ በሬ፥ አራት ድራህማ የሚመዝን ወርቅና ብር ሰጡት።'),
  ('085a5f32-ec23-5415-aa14-52ec7f8893f2', '84413c86-ae6b-52f8-af26-b0bd09b172cb', '48f58ee1-b0d3-5be5-af17-c19673b9bedf', 3, 12, 'እግዚአብሔርም ከፊተኛው ይልቅ የኋለኛውን ለኢዮብ ባረከ፤ መንጋዎቹም ዐሥራ አራት ሺህ በጎች፥ ስድስት ሺህም ግመሎች፥ አንድ ሺህም ጥማድ በሬዎች፥ አንድ ሺህም እንስት አህዮች ነበሩ።'),
  ('a5555ebd-6f51-5573-a98d-711d9207a129', '84413c86-ae6b-52f8-af26-b0bd09b172cb', '48f58ee1-b0d3-5be5-af17-c19673b9bedf', 4, 13, 'ደግሞም ሰባት ወንዶችና ሦስት ሴቶች ልጆች ተወለዱለት።'),
  ('6ae2cae5-4bbd-5c99-a001-35e05b6c405e', '84413c86-ae6b-52f8-af26-b0bd09b172cb', '48f58ee1-b0d3-5be5-af17-c19673b9bedf', 5, 14, 'የመጀመሪያይቱን ስም ዕለት፥ የሁለተኛይቱንም ስም ቃስያ፥ የሦስተኛይቱንም ስም አማልትያስቂራስ ብሎ ሰየማቸው።'),
  ('96a7c1ae-e761-586e-a191-f77064d0c85b', '84413c86-ae6b-52f8-af26-b0bd09b172cb', '48f58ee1-b0d3-5be5-af17-c19673b9bedf', 6, 15, 'ከሰማይ በታች እንደ ኢዮብ ሴቶች ልጆች ያሉ የተዋቡ ሴቶች በሀገሩ ሁሉ አልተገኙም፤ አባታቸውም ከወንድሞቻቸው ጋር ርስት ሰጣቸው።'),
  ('37121e02-932b-5f9f-a694-c5e591aae7df', '84413c86-ae6b-52f8-af26-b0bd09b172cb', '48f58ee1-b0d3-5be5-af17-c19673b9bedf', 7, 16, 'ኢዮብም ከደዌው ከዳነ በኋላ መቶ ሰባ ዓመት ኖረ፥ ኢዮብም የኖረበት ዘመን ሁሉ ሁለት መቶ አርባ ነው። ልጆቹንና የልጅ ልጆቹንም እስከ አራት ትውልድ ድረስ አየ።'),
  ('35804327-d1e6-5b85-ad68-08892925e4f3', '84413c86-ae6b-52f8-af26-b0bd09b172cb', '48f58ee1-b0d3-5be5-af17-c19673b9bedf', 8, 17, 'ኢዮብም ሸምግሎ ዕድሜም ጠግቦ ሞተ።'),
  ('98034fd3-19d3-5a27-a2fd-689b6255c502', '84413c86-ae6b-52f8-af26-b0bd09b172cb', '48f58ee1-b0d3-5be5-af17-c19673b9bedf', 9, 18, 'እግዚአብሔር ከሚያነሣቸው ሰዎች ጋር ዳግመኛ እንደሚነሣ የተጻፈ ነው።'),
  ('ab5cddae-db0e-510e-ac15-b325de855d79', '84413c86-ae6b-52f8-af26-b0bd09b172cb', '48f58ee1-b0d3-5be5-af17-c19673b9bedf', 10, 19, 'ይህ ሰው በሶርያው መጽሐፍ እንደዚህ ተገልጦአል። የኖረበትም ሀገሩ በኤዶምያስና በዐረብ አውራጃ ያለ አውስጢድ ነው።'),
  ('408e2c38-0d18-57b7-a208-1ac2e3b4cfcd', '84413c86-ae6b-52f8-af26-b0bd09b172cb', '48f58ee1-b0d3-5be5-af17-c19673b9bedf', 11, 20, 'ስሙም ቀድሞ ኢዮባብ ነበረ፥ ዐረባዊት ሴትንም አገባ። ስሙ ሄኖን የሚባል ልጅንም ወለደችለት። እርሱም የኤሳው የልጅ ልጅ የዛራ ልጅ ነው። እናቱም ባሱራስ ትባል ነበር።'),
  ('12a6f387-0798-5a82-abf3-10d35bc87f8b', '84413c86-ae6b-52f8-af26-b0bd09b172cb', '48f58ee1-b0d3-5be5-af17-c19673b9bedf', 12, 21, 'እርሱም ከአብርሃም አምስተኛ ነው። እርሱም በገዛት ሀገር በኤዶምያስ የነገሡ ነገሥታት እነዚህ ነበሩ።'),
  ('e750b1e2-018d-56cf-a397-dc0e06a8a79d', '84413c86-ae6b-52f8-af26-b0bd09b172cb', '48f58ee1-b0d3-5be5-af17-c19673b9bedf', 13, 22, 'አስቀድሞ የነገሠ የቢዖር ልጅ ባላቅ ነው። የከተማዋም ስም ዲናባ ነበር።'),
  ('5569df7e-be11-5376-a694-864b61bc108f', '84413c86-ae6b-52f8-af26-b0bd09b172cb', '48f58ee1-b0d3-5be5-af17-c19673b9bedf', 14, 23, 'ከባላቅም በኋላ ስሙ ኢዮብ ይባል የነበረው ኢዮባብ ነገሠ። ከእርሱም በኋላ በቴማን ሀገር የነገሠ አሶም ነበር።'),
  ('bb9990ae-2942-5034-a933-ff117e6792a3', '84413c86-ae6b-52f8-af26-b0bd09b172cb', '48f58ee1-b0d3-5be5-af17-c19673b9bedf', 15, 24, 'ከእርሱም በኋላ በሞዓብ ምድረ በዳ የምድያምን ሰዎች የገደላቸው የበራድ ልጅ አዳድ ነበር፥ የከተማውም ስም ጌቴም ነበር።'),
  ('43260cdf-27a4-5eee-ae56-ef70e8682b8c', '84413c86-ae6b-52f8-af26-b0bd09b172cb', '48f58ee1-b0d3-5be5-af17-c19673b9bedf', 16, 25, 'ወደ እርሱ የመጡ ወዳጆቹም አንዱ ከዔሳው ልጆች የተወለደ በቴማኖን የነገሠው ኤልፋዝ፥ በአውኪኒዮን የተሾመው በልዳዶስና የአሜኔዎን ንጉሥ ሶፋር ነበሩ።'),
  ('96378cf9-4953-56a5-ae15-592968696d09', 'd72fa03a-1ab4-5023-aef0-736d4bad06d3', 'f640edb7-c655-5503-a66f-ec664e730176', 1, 1, 'ምስጉን ነው በክፉዎች ምክር ያልኼደ በኀጢአተኛዎችም መንገድ ያልቆመ በዋዘኛዎችም ወንበር ያልተቀ መጠ'),
  ('56cf8615-e799-5a6b-a467-7bba7f2ac5a6', 'd72fa03a-1ab4-5023-aef0-736d4bad06d3', 'f640edb7-c655-5503-a66f-ec664e730176', 2, 2, 'ነገር ግን በእግዚአብሔር ሕግ ደስ ይለዋል ሕጉንም በቀንና በሌሊት ያስባል'),
  ('7e0e7d41-c535-51b4-ac4d-78bbf7b741b1', 'd72fa03a-1ab4-5023-aef0-736d4bad06d3', 'f640edb7-c655-5503-a66f-ec664e730176', 3, 3, 'ርሱም በውሃ ፈሳሾች ዳር እንደ ተተከለች ፍሬዋን በየጊዜዋ እንደምትሰጥ ቅጠሏም እንደማይረግፍ ዛ ፍ ይኾናል የሚሠራውም ዅሉ ይከናወንለታል'),
  ('c639a34b-ad20-5f45-a194-5fe59c1380f1', 'd72fa03a-1ab4-5023-aef0-736d4bad06d3', 'f640edb7-c655-5503-a66f-ec664e730176', 4, 4, 'ክፉዎች እንዲህ አይደሉም ነገር ግን ነፋስ ጠርጎ እንደሚወስደው ትቢያ ናቸው'),
  ('02889721-9a31-5f23-a3a0-f37e674fa5d2', 'd72fa03a-1ab4-5023-aef0-736d4bad06d3', 'f640edb7-c655-5503-a66f-ec664e730176', 5, 5, 'ስለዚህ ክፉዎች በፍርድ ኀጢአተኛዎችም በጻድቃን ማኅበር አይቆሙም'),
  ('d859a031-d909-5889-adc2-52792c0041da', 'd72fa03a-1ab4-5023-aef0-736d4bad06d3', 'f640edb7-c655-5503-a66f-ec664e730176', 6, 6, 'እግዚአብሔር የጻድቃንን መንገድ ያውቃልና የክፉዎች መንገድ ግን ትጠፋለች'),
  ('b9a0c42e-7996-5c28-a433-237dd701f5e5', '614c2321-7940-588f-a12b-e691a9dd2ba0', '438cc212-f8c0-53ec-aac3-dff8a7b56c37', 1, 1, 'አሕዛብ ለምን ያጕረመርማሉ ወገኖችስ ለምን ከንቱን ይናገራሉ'),
  ('20110a76-d849-5782-a867-63619b035576', '614c2321-7940-588f-a12b-e691a9dd2ba0', '438cc212-f8c0-53ec-aac3-dff8a7b56c37', 2, 2, 'የምድር ነገሥታት ተነሡ አለቃዎችም በእግዚአብሔርና በመሲሑ ላይ እንዲህ ሲሉ ተማከሩ'),
  ('8a4ad3fe-7691-5908-a222-1d5ca697b254', '614c2321-7940-588f-a12b-e691a9dd2ba0', '438cc212-f8c0-53ec-aac3-dff8a7b56c37', 3, 3, 'ማሰሪያቸውን እንበጥስ ገመዳቸውንም ከእኛ እንጣል'),
  ('da9ea230-6ac9-5ee3-a825-0b49a90cbfd6', '614c2321-7940-588f-a12b-e691a9dd2ba0', '438cc212-f8c0-53ec-aac3-dff8a7b56c37', 4, 4, 'በሰማይ የሚኖር ርሱ ይሥቃል ጌታም ይሣለቅባቸዋል'),
  ('7a3be352-7e45-5cd2-a9be-283ab654e753', '614c2321-7940-588f-a12b-e691a9dd2ba0', '438cc212-f8c0-53ec-aac3-dff8a7b56c37', 5, 5, 'በዚያን ጊዜ በቍጣው ይናገራቸዋል በመዓቱም ያውካቸዋል'),
  ('610a9b99-bb49-5067-a058-4f8627f331d5', '614c2321-7940-588f-a12b-e691a9dd2ba0', '438cc212-f8c0-53ec-aac3-dff8a7b56c37', 6, 6, 'እኔ ግን ንጉሤን ሾምኹ በተቀደሰው ተራራዬ በጽዮን ላይ'),
  ('b01bd80f-d23e-5518-af55-a8850e225a23', '614c2321-7940-588f-a12b-e691a9dd2ba0', '438cc212-f8c0-53ec-aac3-dff8a7b56c37', 7, 7, 'ትእዛዙን እናገራለኹ እግዚአብሔር አለኝ፦አንተ ልጄ ነኽ እኔ ዛሬ ወለድኹኽ'),
  ('8dd99d13-6abc-5427-a4ac-f30c6b2b45b2', '614c2321-7940-588f-a12b-e691a9dd2ba0', '438cc212-f8c0-53ec-aac3-dff8a7b56c37', 8, 8, 'ለምነኝ አሕዛብን ለርስትኽ የምድርንም ዳርቻ ለግዛትኽ እሰጥኻለኹ'),
  ('795f7439-a13b-58c7-adcd-4ea130223126', '614c2321-7940-588f-a12b-e691a9dd2ba0', '438cc212-f8c0-53ec-aac3-dff8a7b56c37', 9, 9, 'በብረት በትር ትጠብቃቸዋለኽ እንደ ሸክላ ሠሪ ዕቃዎች ትቀጠቅጣቸዋለኽ'),
  ('0e9de80f-63e5-55ab-a4dc-fb793cc5f494', '614c2321-7940-588f-a12b-e691a9dd2ba0', '438cc212-f8c0-53ec-aac3-dff8a7b56c37', 10, 10, 'አኹንም እናንት ነገሥታት ልብ አድርጉ እናንት የምድር ፈራጆችም ተገሠጹ'),
  ('fc46f976-9782-5d68-a838-36f78db34b26', '614c2321-7940-588f-a12b-e691a9dd2ba0', '438cc212-f8c0-53ec-aac3-dff8a7b56c37', 11, 11, 'ለእግዚአብሔር በፍርሀት ተገዙ በረዓድም ደስ ይበላችኹ'),
  ('fe4b1072-142a-5eb3-a96a-0dec5a3c9c98', '614c2321-7940-588f-a12b-e691a9dd2ba0', '438cc212-f8c0-53ec-aac3-dff8a7b56c37', 12, 12, 'ተግሣጹን ተቀበሉ ጌታ እንዳይቈጣ እናንተም በመንገድ እንዳትጠፉ ቍጣው ፈጥና ትነዳ፟ለችና በርሱ የታመኑ ዅሉ የተመሰገኑ ናቸው'),
  ('eb6214f0-eaf6-52d3-a077-3d7054b15b19', '3199ceab-315d-5397-a2ba-8d891eea617c', 'c280445f-4ad1-57f7-aba2-b73e8bfb5b98', 1, 1, 'አቤቱ የሚያስጨንቁኝ ምንኛ በዙ! በእኔ ላይ የሚቆሙት ብዙ ናቸው'),
  ('92eed20e-9403-594e-a16a-7a8759d63e00', '3199ceab-315d-5397-a2ba-8d891eea617c', 'c280445f-4ad1-57f7-aba2-b73e8bfb5b98', 2, 2, 'ብዙ ሰዎች ነፍሴን፦አምላክሽ አያድንሽም አሏት'),
  ('ad8090cb-75b2-5360-a584-44d213667b4a', '3199ceab-315d-5397-a2ba-8d891eea617c', 'c280445f-4ad1-57f7-aba2-b73e8bfb5b98', 3, 3, 'አንተ ግን አቤቱ መጠጊያዬ ነኽ ክብሬንና ራሴንም ከፍ ከፍ የምታደርገው አንተ ነኽ'),
  ('66896e80-3bcc-5483-a4c3-f7da1fc4ef61', '3199ceab-315d-5397-a2ba-8d891eea617c', 'c280445f-4ad1-57f7-aba2-b73e8bfb5b98', 4, 4, 'በቃሌ ወደ እግዚአብሔር እጮኻለኹ ከተቀደሰ ተራራውም ይሰማኛል'),
  ('ed827423-d74d-527b-a8bb-6908fc9c58f7', '3199ceab-315d-5397-a2ba-8d891eea617c', 'c280445f-4ad1-57f7-aba2-b73e8bfb5b98', 5, 5, 'እኔ ተኛኹ አንቀላፋኹም እግዚአብሔርም ደግፎኛልና ነቃኹ'),
  ('0c259bd6-cacf-56e4-a107-6efd83f1e364', '3199ceab-315d-5397-a2ba-8d891eea617c', 'c280445f-4ad1-57f7-aba2-b73e8bfb5b98', 6, 6, 'ከሚከቡ፟ኝ ከአእላፍ ሕዝብ አልፈራም'),
  ('482bbdb3-1ad8-5df7-a1b6-4bad4b3df325', '3199ceab-315d-5397-a2ba-8d891eea617c', 'c280445f-4ad1-57f7-aba2-b73e8bfb5b98', 7, 7, 'ተነሥ አቤቱ አምላኬ ሆይ አድነኝ አንተ የጠላቶቼን መንጋጋ መትተኻልና የክፉዎችንም ጥርስ ሰብረኻ ልና'),
  ('bbffdf5a-fb03-5af4-a114-ba05436bc6e4', '3199ceab-315d-5397-a2ba-8d891eea617c', 'c280445f-4ad1-57f7-aba2-b73e8bfb5b98', 8, 8, 'ማዳን የእግዚአብሔር ነው በረከትኽም በሕዝብኽ ላይ ነው'),
  ('10adbc58-193b-5331-ae5d-632410818133', '1f77d61f-c4c6-5b0d-a433-5e5eea6b7d11', 'be52487a-3471-5a61-ab20-ae6695da0a06', 1, 1, 'የጽድቄ አምላክ በጠራኹት ጊዜ መለሰልኝ በጭንቀቴም አሰፋኽልኝ ማረኝ ጸሎቴንም ስማ'),
  ('ad636f5e-cbbe-5e97-af6c-c885f67c1a44', '1f77d61f-c4c6-5b0d-a433-5e5eea6b7d11', 'be52487a-3471-5a61-ab20-ae6695da0a06', 2, 2, 'እናንት የሰው ልጆች እስከ መቼ ድረስ ልባችኹን ታከብዳላችኹ'),
  ('1ecae6b9-6183-5977-a9ba-79d9d8e9b36a', '1f77d61f-c4c6-5b0d-a433-5e5eea6b7d11', 'be52487a-3471-5a61-ab20-ae6695da0a06', 3, 3, 'እግዚአብሔር በጻድቁ እንደ ተገለጠ ዕወቁ እግዚአብሔር ወደ ርሱ በተጣራኹ ጊዜ ይሰማኛል'),
  ('c7b5f5f3-d605-5082-a9a4-ecca3c40d3e6', '1f77d61f-c4c6-5b0d-a433-5e5eea6b7d11', 'be52487a-3471-5a61-ab20-ae6695da0a06', 4, 4, 'ተቈጡ ነገር ግን ኀጢአትን አታድርጉ በመኝታችኹ ሳላችኹ በልባችኹ ዐስቡ ዝም በሉ'),
  ('d29c75fa-6f1e-5d09-a016-2975f47f58b7', '1f77d61f-c4c6-5b0d-a433-5e5eea6b7d11', 'be52487a-3471-5a61-ab20-ae6695da0a06', 5, 5, 'የጽድቅን መሥዋዕት ሠዉ በእግዚአብሔርም ታመኑ'),
  ('a24f3653-7b89-5b27-a834-8a394dab11e6', '1f77d61f-c4c6-5b0d-a433-5e5eea6b7d11', 'be52487a-3471-5a61-ab20-ae6695da0a06', 6, 6, 'በጎውን ማን ያሳየናል የሚሉ ብዙ ናቸው አቤቱ የፊትኽ ብርሃን በላያችን ታወቀ'),
  ('0e09470b-f9bf-5185-a879-a7056c9f308a', '1f77d61f-c4c6-5b0d-a433-5e5eea6b7d11', 'be52487a-3471-5a61-ab20-ae6695da0a06', 7, 7, 'በልቤ ደስታን ጨመርኽ ከስንዴ ፍሬና ከወይን ከዘይትም ይልቅ በዛ'),
  ('f6196b5d-21e2-5605-a79c-38cd521e8fe9', '1f77d61f-c4c6-5b0d-a433-5e5eea6b7d11', 'be52487a-3471-5a61-ab20-ae6695da0a06', 8, 8, 'በሰላም እተኛለኹ አንቀላፋለኹም አቤቱ አንተ ብቻኽን በእምነት አሳድረኸኛልና'),
  ('fc66366a-bdaa-5b75-a255-e99e1c7e61ae', '2560c473-41c5-531b-a645-8f218ff54b14', 'fd2f22bf-09fe-5f8e-a3b6-7b17201dd956', 1, 1, 'አቤቱ ቃሌን አድምጥ ጩኸቴንም አስተውል'),
  ('386feb2e-af15-5408-af2b-5ca9e9d355be', '2560c473-41c5-531b-a645-8f218ff54b14', 'fd2f22bf-09fe-5f8e-a3b6-7b17201dd956', 2, 2, 'የልመናዬን ቃል አድምጥ ንጉሤና አምላኬ ሆይ አቤቱ ወዳንተ እጸልያለኹና'),
  ('f6a9b106-cbe2-5653-aed0-a3e5b921642d', '2560c473-41c5-531b-a645-8f218ff54b14', 'fd2f22bf-09fe-5f8e-a3b6-7b17201dd956', 3, 3, 'በማለዳ ድምፄን ትሰማለኽ በማለዳ በፊትኽ እቆማለኹ እጠብቃለኹም'),
  ('9ccdf4ac-d82d-5659-ac34-ca867b9d747a', '2560c473-41c5-531b-a645-8f218ff54b14', 'fd2f22bf-09fe-5f8e-a3b6-7b17201dd956', 4, 4, 'አንተ በደልን የማትወድ፟ አምላክ ነኽና ክፉ ከአንተ ጋራ አያድርም'),
  ('d779a78f-2d25-5f82-ac20-71b36ec485dc', '2560c473-41c5-531b-a645-8f218ff54b14', 'fd2f22bf-09fe-5f8e-a3b6-7b17201dd956', 5, 5, 'በከንቱ የሚመኩ በዐይኖችኽ ፊት አይኖሩም ክፉ አድራጊዎችን ዅሉ ጠላኽ'),
  ('b3a364ad-6ef5-542b-a502-b5a81addb707', '2560c473-41c5-531b-a645-8f218ff54b14', 'fd2f22bf-09fe-5f8e-a3b6-7b17201dd956', 6, 6, 'ሐሰትን የሚናገሩትን ታጠፋቸዋለኽ ደም አፍሳሹንና ሸንጋዩን ሰው እግዚአብሔር ይጸየፋል'),
  ('f045241b-ca09-5051-a770-4793677a89b8', '2560c473-41c5-531b-a645-8f218ff54b14', 'fd2f22bf-09fe-5f8e-a3b6-7b17201dd956', 7, 7, 'እኔ ግን በምሕረትኽ ብዛት ወደ ቤትኽ እገባለኹ አንተን በመፍራት ወደ ቅድስናኽ መቅደስ እሰግዳለ ኹ'),
  ('4417d705-c413-596c-a8c7-5f254e7df8f5', '2560c473-41c5-531b-a645-8f218ff54b14', 'fd2f22bf-09fe-5f8e-a3b6-7b17201dd956', 8, 8, 'አቤቱ ስለ ጠላቶቼ በጽድቅኽ ምራኝ መንገዴን በፊትኽ አቅና'),
  ('c5ea0880-663b-5a7d-ace8-5318671dac6c', '2560c473-41c5-531b-a645-8f218ff54b14', 'fd2f22bf-09fe-5f8e-a3b6-7b17201dd956', 9, 9, 'በአፋቸው እውነት የለምና ልባቸውም ከንቱ ነው ጕረሯቸው የተከፈተ መቃብር ነው በምላሳቸው ይሸነግ ላሉ'),
  ('1d936307-a023-5adf-afb7-f8410e4613c8', '2560c473-41c5-531b-a645-8f218ff54b14', 'fd2f22bf-09fe-5f8e-a3b6-7b17201dd956', 10, 10, 'አቤቱ ፍረድባቸው በምክራቸውም ይውደቁ ስለ ክፋታቸውም ብዛት አሳዳ፟ቸው እነርሱ ዐምፀውብኻልና'),
  ('c5a9fcb8-bc17-5ef8-a428-873f3c923e8a', '2560c473-41c5-531b-a645-8f218ff54b14', 'fd2f22bf-09fe-5f8e-a3b6-7b17201dd956', 11, 11, 'ባንተ የሚታመኑት ዅሉ ግን ደስ ይላቸዋል ለዘለዓለሙ ደስ ይላቸዋል እነርሱንም ትጠብቃለኽ ስምኽ ንም የሚወዱ ዅሉ ባንተ ይመካሉ'),
  ('61324474-fe5a-522e-afa2-5b317c480c65', '2560c473-41c5-531b-a645-8f218ff54b14', 'fd2f22bf-09fe-5f8e-a3b6-7b17201dd956', 12, 12, 'አንተ ጻድቁን ትባርከዋለኽና አቤቱ እንደ ጋሻ በሞገስ ከለልኸን'),
  ('30a19380-5f75-5dce-a00e-252ed4acaad2', '36ea182b-faf3-5879-a600-36cac4f63fa0', '7e0e3158-d733-55ad-ae28-9f1b16a11366', 1, 1, 'አቤቱ በቍጣኽ አትቅሠፈኝ በመዓትኽም አትገሥጸኝ'),
  ('2354c343-0417-5c55-aa98-119a4fe7316d', '36ea182b-faf3-5879-a600-36cac4f63fa0', '7e0e3158-d733-55ad-ae28-9f1b16a11366', 2, 2, 'ድውይ ነኝና አቤቱ ማረኝ ዐጥንቶቼ ታውከዋልና ፈውሰኝ'),
  ('48908e15-d0c8-5136-a232-efbbae410859', '36ea182b-faf3-5879-a600-36cac4f63fa0', '7e0e3158-d733-55ad-ae28-9f1b16a11366', 3, 3, 'ነፍሴም እጅግ ታወከች አንተም አቤቱ እስከ መቼ ድረስ ነው'),
  ('d1505250-8cd5-54a3-aa29-58f4dcd183f7', '36ea182b-faf3-5879-a600-36cac4f63fa0', '7e0e3158-d733-55ad-ae28-9f1b16a11366', 4, 4, 'አቤቱ ተመለስ ነፍሴንም አድናት ስለ ቸርነትኽም አድነኝ'),
  ('ea87a3cc-1b5f-5f06-ae12-cb92e0b46391', '36ea182b-faf3-5879-a600-36cac4f63fa0', '7e0e3158-d733-55ad-ae28-9f1b16a11366', 5, 5, 'በሞት የሚያስብኽ የለምና በሲኦልም የሚያመሰግንኽ ማን ነው'),
  ('3755af64-e884-5b3c-a61c-eb39262b78e6', '36ea182b-faf3-5879-a600-36cac4f63fa0', '7e0e3158-d733-55ad-ae28-9f1b16a11366', 6, 6, 'በጭንቀቴ ደክሜያለኹ ሌሊቱን ዅሉ ዐልጋዬን ዐጥባለኹ በዕንባዬም መኝታዬን አርሳለኹ'),
  ('57ee80ce-f014-5478-ad4b-5000d9b5053a', '36ea182b-faf3-5879-a600-36cac4f63fa0', '7e0e3158-d733-55ad-ae28-9f1b16a11366', 7, 7, 'ዐይኔ ከቍጡ ዕንባ የተነሣ ታወከች ከጠላቶቼ ዅሉ የተነሣ አረጀኹ'),
  ('2eb8c3af-3f2d-5e5d-a8bd-cdc8d083f37c', '36ea182b-faf3-5879-a600-36cac4f63fa0', '7e0e3158-d733-55ad-ae28-9f1b16a11366', 8, 8, 'ዐመፃን የምታደርጉ ዅሉ ከእኔ ራቁ እግዚአብሔር የልቅሶዬን ቃል ሰምቷልና'),
  ('c2fc67a1-03c9-5fff-a128-bd631bc07895', '36ea182b-faf3-5879-a600-36cac4f63fa0', '7e0e3158-d733-55ad-ae28-9f1b16a11366', 9, 9, 'እግዚአብሔር ልመናዬን ሰማኝ እግዚአብሔር ጸሎቴን ተቀበለ'),
